(* [comment removed for export] *)
Definition pf_vals (regs : bvmap 5 word) (sp : word) (w can : Z) : list word :=
  [sp; Z_to_bv 64 w; Z_to_bv 64 can] ++ junk_vals regs.

Definition pfE (regs : bvmap 5 word) (sp : word) (w can : Z) : env :=
  Env (vals_ev (pf_vals regs sp w can)) (blobs_ev []).

Definition pf_sr : list expr :=
  Eval cbv in (map (fun i => match i with
                          | 0 => ELit 0 | 1 => ELit 0x17c14 | 2 => EVar 0 | 11 => ELit 0
                          | _ => EVar (3 + i) end)%nat (seq 0 32)).

Definition pf_kn : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) 0x77420 0x7fffffffffff;
   KWr (SA (EVar 0) (-1056)) 1056;
   KImg 0x10000 0x45000;
   KWord (SA (ELit 0) 0x46020) 4 (ELit 5);
   KWord (SA (ELit 0) 0x46040) 8 (ELit 0x76d40);
   KWord (SA (ELit 0) 0x46048) 8 (EVar 1);
   KRange (EVar 1) 0x76940 0x76d3e;
   KWord (SA (ELit 0) 0x46080) 8 (ELit 1024);
   KWord (SA (ELit 0) 0x460ac) 4 (ELit 4294967295);
   KWord (SA (ELit 0) 0x460b0) 4 (ELit 4294967295);
   KWord (SA (ELit 0) 0x764d8) 8 (EVar 2);
   KWr (SA (ELit 0) 0x45000) 0x2000;
   KWr (SA (EVar 1) 0) 2].

